native_argv:
& {
  $ErrorActionPreference = 'Stop'
  $project = '<project>'
  $unityExe = '<checked version-resolved Editor>'
  $log = '<fresh absolute unity log>'
  $audit = $log + '.outer-audit.json'
  $stem = [IO.Path]::Combine([IO.Path]::GetDirectoryName($log), [IO.Path]::GetFileNameWithoutExtension($log))
  foreach ($path in @($log, $audit, ($stem + '.stdout.log'), ($stem + '.stderr.log'))) {
    if (Test-Path -LiteralPath $path) { throw ('Fresh evidence path required: ' + $path) }
  }
  $unityArguments = @('-buildTarget', 'Android', '-executeMethod', 'Game.Editor.SkirmishS002AriaRunHarness.RunProductionPaidPlaneSupplementFromEnvironment')
  $requiredMarkers = @(
    '[S005NormalPaidPlaneLineage] result=Passed scope=NormalAirportPlaneDeliveryOnly fullMissionCertified=0 playerReady=0',
    '[S005NormalPaidPlaneCruise] result=Passed scope=NormalPaidTransportCruiseCameraOnly fullMissionCertified=0 playerReady=0'
  )
  $errors = [Collections.Generic.List[string]]::new()
  $counts = @{}
  $actualWrapperExit = $null
  try {
    $global:LASTEXITCODE = $null
    & (Join-Path $project 'Tools/CI/InvokeUnity.ps1') -UnityExe $unityExe -ProjectPath $project -LogFile $log -NoProcessExit -GuiLicensing -TimeoutSeconds 3600 -UnityArguments $unityArguments
    $actualWrapperExit = $LASTEXITCODE
    if ($null -eq $actualWrapperExit -or $actualWrapperExit -ne 0) { $errors.Add('Actual checked wrapper exit is missing/nonzero/timeout') }
    if (-not (Test-Path -LiteralPath $log -PathType Leaf)) { $errors.Add('Native wrapper log missing') }
    else {
      $text = [IO.File]::ReadAllText($log)
      $lines = $text -split '\r?\n'
      foreach ($marker in $requiredMarkers) {
        $counts[$marker] = @($lines | Where-Object { $_ -ceq $marker }).Count
        if ($counts[$marker] -ne 1) { $errors.Add('Missing or duplicated exact scoped marker: ' + $marker) }
      }
      if (@($lines | Where-Object { $_ -ceq '[UnityInvoke] ExitCode: 0' }).Count -ne 1) { $errors.Add('Exact real wrapper zero-exit log witness missing/duplicated') }
      if ($text -match 'process exit code was unavailable') { $errors.Add('Wrapper inferred an exit from a marker; actual exit remains unproven') }
      if ($text -match 'result=Failed|error CS\d+|Unhandled Exception|AssertionException|StackOverflowException|executeMethod.*threw exception|Aborting.*failure|already open in another Unity instance') { $errors.Add('Actual failure/compiler/exception/project-lock evidence preserved') }
    }
  } catch { $errors.Add($_.Exception.Message) }
  $receipt = @{ schema_version = 1; scope = 'PaidTransportSupplementOuterAuditOnly'; wrapper_exit = $actualWrapperExit; unity_arguments = $unityArguments; required_marker_counts = $counts; errors = $errors.ToArray(); outer_audit_passed = ($errors.Count -eq 0); native_qualification = 'PendingTypedTransactionJoinsSourceBuildClosureAndIndependentReview'; normal_mission_accepted = $false; queue_success_enabled = $false; normal_720_credit = 0 }
  $bytes = [Text.UTF8Encoding]::new($false).GetBytes(($receipt | ConvertTo-Json -Depth 8) + [Environment]::NewLine)
  $stream = [IO.File]::Open($audit, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::Read)
  try { $stream.Write($bytes, 0, $bytes.Length) } finally { $stream.Dispose() }
  if ($errors.Count -ne 0) { throw ('Paid transport outer audit failed; preserve receipt: ' + $audit) }
}
